"""Workpeg app chrome — the :class:`Scaffold` widget and its sidebar pieces.

:class:`Scaffold` is the standard Workpeg application shell: a fixed left
sidebar, a ``main`` content area, and an optional ``attached`` panel to the
right of ``main``. The sidebar is built-in chrome — the Workpeg logo with a
collapse toggle, the **Search** and **Workpeg AI** entries, then *your* nav
(the ``sidebar`` slot), and the business switcher pinned at the foot. It is
self-contained: it gates on the signed-in session and loads the user's
businesses itself, so a host supplies only the slots — never auth or a
business list — and the surrounding chrome (collapse/expand, the business
popup, the gravatar) comes for free::

    from workpeg.ui import Scaffold, NavItem, NavSection, Outlet

    Scaffold(
        NavItem("Home", "/", icon="home"),         # ── sidebar children ──
        NavSection("Private", NavItem("Kanban", "/kanban")),
        main=Outlet(),                             # the page body
        attached=Inspector(),                      # optional; hidden if omitted
    )

The sidebar nav is passed positionally (its children); ``main`` and
``attached`` are the other two slots.

**The chrome is bundle-drawn.** Scaffold is a *special widget*: an app
compiles only its own customization (the slots above); everything around
them — the shell layout, the rail's header/Search/Workpeg AI rows, the
business switcher, the top-nav actions, the Apps launcher — is drawn at
runtime by the standalone ``scaffold.js`` (bundled next to the app and
published to the CDN, exactly like the ``ai.js`` chat surface). That lets the
Workpeg team update the shell's design *out of band*: a new scaffold.js
re-skins every app without a rebuild. The compiled slot content renders into
stable slot roots that scaffold.js adopts into the chrome it draws.

Sidebar collapse is internal — the chrome's own toggle button owns it. It's
purely visual (a ``.pg-collapsed`` class the toggle flips on ``<html>``,
animated via CSS custom properties), so a host's nav needs no collapse flag.
Mount it under a ``/b/<business_uuid>`` route — it reads the active business
from the URL and every link it builds is ``/b/<business_uuid>/…``.
:class:`NavItem`, :class:`NavSection`, :class:`NavHR` (a divider line),
:class:`WorkspaceItem` and :class:`UserSwitcher` are exported too so a host can
compose its own nav and reuse the same look. Each NavItem href is
business-scoped to ``/b/<business_id>/...`` — the Workpeg routing convention.
"""
from workpeg.ui.app import (
    Component, State, infinity, navigate, user,
)
from workpeg.ui.widgets import (
    Authenticated, Column, Container, Expanded, GestureDetector,
    GravatarImage, Icon, Link, Menu, Row, ScaffoldSlots, SizedBox, Spacer,
    Text,
)

# Sidebar-collapse animation. The chrome never re-renders to collapse — it reads
# its padding, width, opacity and grow from the ``--pg-collapse-*`` custom
# properties that ``toggle_sidebar()`` swaps on <html> (see pegment.css), so
# these inline transitions fire on the persistent DOM.
#
# Each item is `glyph + label/region`. The glyph (icon/avatar/toggle) is the
# row's left-most child, so its x is set purely by the item's **left padding**,
# which we animate to re-centre it — a single eased length, hence a monotonic
# glide with no end-snap. The label/region beside it is `flex:1` and simply
# fades (opacity) while the narrowing rail squeezes its width, so it never tugs
# the glyph. (Plain adjacent-string constants so the compiler inlines them
# wherever they're used as style values.)
_TR_PAD = "padding-left 0.18s cubic-bezier(0.4, 0, 0.2, 1)"
_TR_OP = "opacity 0.18s cubic-bezier(0.4, 0, 0.2, 1)"
_TR_FLEX_OP = ("flex-grow 0.18s cubic-bezier(0.4, 0, 0.2, 1), "
               "opacity 0.18s cubic-bezier(0.4, 0, 0.2, 1)")
# HidingNavItem: the whole row collapses away — height to 0 + fade, in step
# with the rail.
_TR_HIDE = ("height 0.18s cubic-bezier(0.4, 0, 0.2, 1), "
            "opacity 0.18s cubic-bezier(0.4, 0, 0.2, 1)")


class NavLabel(Component):
    """The label region of a sidebar nav row — the content that sits beside the
    icon. It's the collapse **text-hide**, lifted out of :class:`NavItem` into
    its own widget so a host can reuse it: wrap your own row's text in it and it
    fades out and is squeezed away when the rail collapses, exactly like the
    built-in items (the icon beside it stays put and re-centres)::

        Row(Icon("home", size=18), NavLabel(Text("Home")),
            align="center", gap=6)

    Pass the label content positionally — a ``Text``, or a ``Text`` plus a
    trailing ``Spacer()`` and a badge/chevron. It fills the row's free width and
    clips on one line (no wrap) as the rail narrows. Spacing from the icon is the
    parent ``Row``'s ``gap`` (not a margin here), so it composes cleanly."""

    def __init__(self, *content):
        self.content = content

    def build(self):
        return Container(
            Row(*self.content, align="center", gap=0),
            style={
                "flex": "1", "minWidth": "0", "overflow": "hidden",
                "whiteSpace": "nowrap",
                # The collapse text-hide: fades with the rail's opacity var
                # (0 when `.pg-collapsed`), transitioning in step with it.
                "opacity": "var(--pg-collapse-op)",
                "transition": _TR_OP,
            },
        )


class _NavLabelText(Component):
    """The row's label — Label LG (14px) at medium-450, one line,
    ellipsis-clipped. Shared by every NavItem variant."""

    def __init__(self, label):
        self.label = label

    def build(self):
        return Text(self.label, style={
            "fontSize": "14px", "fontWeight": "450", "lineHeight": "16px",
            "whiteSpace": "nowrap", "overflow": "hidden",
            "textOverflow": "ellipsis",
            "color": "var(--color-text-primary)"})


class _ActionIconBox(Component):
    """A 24px hover-revealed action icon (pin, star, ⋯). The icon inherits
    the box's ``color`` (currentColor via the CSS mask), so it flips
    icon-secondary → white on hover; the box slides in (translateX 4px →
    0) on row hover. Used both as a tappable button (wrapped in a
    :class:`GestureDetector`) and as the ⋯ :class:`Menu`'s trigger.

    The resting colour lives in ``:rest`` (not inline) so the ``:hover`` class
    rule can win, and the slide lives here (not on the tray) so no transformed
    ancestor breaks the ⋯ menu's ``position:fixed`` panel."""

    def __init__(self, icon):
        self.icon = icon

    def build(self):
        return Container(
            Icon(self.icon, size=14),
            style={
                "display": "flex", "alignItems": "center",
                "justifyContent": "center",
                "width": "24px", "height": "24px",
                "borderRadius": "var(--radius-sm)",
                "cursor": "pointer", "flexShrink": "0",
                "transition": "transform 0.18s cubic-bezier(0.4,0,0.2,1)",
                ":rest": {"color": "var(--color-icon-secondary)",
                          "transform": "translateX(4px)"},
                ":link-hover": {"transform": "translateX(0)"},
                ":hover": {"background": "var(--color-bg-active)",
                           "color": "var(--color-text-primary)"},
            })


class _NavMenuRow(Component):
    """One row of the ⋯ overflow menu — icon + label. ``tone="danger"``
    paints it red; a truthy ``disabled`` makes it faint + ``not-allowed`` and
    inert (its tap is a no-op, so it never fires ``on_menu``). A live row fires
    ``on_menu(name, context)`` — the NavItem's caller-supplied context dict.

    ``tone`` and ``disabled`` are OPTIONAL in the item dict: the subscripts
    below compile to JS, where a missing key reads ``undefined`` (falsy) — not
    a KeyError — so an absent key simply means "plain row"."""

    def __init__(self, item, on_menu, context):
        self.item = item
        self.on_menu = on_menu
        self.context = context

    def build(self):
        return GestureDetector(
            Container(
                Row(
                    Icon(self.item["icon"], size=16,
                         color=("var(--color-critical-500)"
                                if self.item["tone"] == "danger"
                                else "var(--color-icon-primary)")),
                    # The label is critical-text; the icon keeps the
                    # brighter -500. Text needs 4.5:1, and -500 was 3.76:1
                    # on the dark menu and 4.16:1 on the light hover; an
                    # icon needs 3:1, which -500 meets in both.
                    Text(self.item["label"], style={
                        "fontSize": "14px", "lineHeight": "normal",
                        "whiteSpace": "nowrap",
                        "color": ("var(--color-critical-text)"
                                  if self.item["tone"] == "danger"
                                  else "var(--color-text-primary)")}),
                    align="center", gap=10),
                style={
                    "display": "flex", "alignItems": "center",
                    "height": "34px", "padding": "0 9px",
                    "borderRadius": "var(--radius)", "boxSizing": "border-box",
                    "width": "100%",
                    # Disabled: faint + not-allowed cursor and no hover
                    # highlight; the tap is guarded to a no-op below, so it
                    # never toasts.
                    "opacity": ("0.4" if self.item["disabled"] else "1"),
                    "cursor": ("not-allowed" if self.item["disabled"]
                               else "pointer"),
                    ":hover": {
                        "background": ("transparent" if self.item["disabled"]
                                       else "var(--color-surface-sunken2)")}}),
            on_tap=lambda: (None if self.item["disabled"]
                            else self.on_menu(self.item["name"],
                                              self.context)))


class _NavActionTray(Component):
    """The hover-revealed trailing action tray shared by every NavItem variant:
    the ``actions`` icon buttons (pin, star, …) then the optional overflow
    ⋯ :class:`Menu`, which flies out to the *right* of the rail (its
    ``menu`` rows, danger in red, disabled faint). It reveals on ROW hover
    (``:link-hover`` — scoped to the enclosing ``<a>``) and reserves NO
    width at rest, so a long label owns the full row until hovered.

    Every fire carries the NavItem's ``context`` (a caller-supplied dict)
    through to ``on_action(name, context)`` / ``on_menu(name, context)``.
    Renders a hidden, zero-width placeholder when the item has neither actions
    nor a menu, so a variant can drop it in unconditionally."""

    def __init__(self, actions, on_action, menu, on_menu, context):
        self.actions = actions if actions else []
        self.on_action = on_action
        self.menu = menu if menu else []
        self.on_menu = on_menu
        self.context = context

    def build(self):
        if not self.actions and len(self.menu) == 0:
            return Container(style={"display": "none", "width": "0"})
        return Container(
            Row(
                *[GestureDetector(
                    _ActionIconBox(a),
                    on_tap=lambda: self.on_action(a, self.context))
                  for a in self.actions],
                # The overflow ⋯ menu: an icon-box trigger + a panel of
                # _NavMenuRow rows that flies out to the RIGHT of the rail. The
                # Menu closes itself on an outside click / Esc / scroll.
                (Menu(
                    _ActionIconBox("dots"),
                    Container(
                        Column(
                            # `key` gives each row its own stable instance, so
                            # its tap closure reads its OWN item (without a key
                            # the reconciler shares one instance and every row
                            # fires the last item's handler).
                            *[_NavMenuRow(m, self.on_menu, self.context,
                                          key=m["name"])
                              for m in self.menu],
                            gap=1, align="stretch"),
                        style={"width": "180px", "boxSizing": "border-box"}),
                    placement="right")
                 if len(self.menu) > 0
                 else Container(style={"display": "none", "width": "0"})),
                align="center", gap=4,
            ),
            style={
                "display": "flex", "alignItems": "center",
                "flexShrink": "0", "overflow": "hidden",
                "transition":
                    "max-width 0.18s cubic-bezier(0.4, 0, 0.2, 1), "
                    "opacity 0.18s cubic-bezier(0.4, 0, 0.2, 1)",
                # Reserve NO space at rest — max-width 0 collapses the tray
                # so a long label owns the full row until hovered. Resting state
                # in the SHEET (:rest) so the a:hover rule can out-specify it.
                # The slide lives on the items (_ActionIconBox), NOT here —
                # a transform on this tray would become the containing block for
                # the ⋯ menu's position:fixed panel and throw it off-screen.
                ":rest": {"max-width": "0", "opacity": "0",
                          "pointer-events": "none"},
                ":link-hover": {"max-width": "120px", "opacity": "1",
                                "pointer-events": "auto"},
            },
        )


class NavItem(Component):
    """A sidebar nav row. Pass extra ``NavItem``\\ s positionally to make it open
    a flyout to the right (a nested :class:`Menu`) instead of navigating — those
    items float in their own panel and the sidebar stays put::

        NavItem("Help", biz_url("/help"), icon="help",
                NavItem("Help Center", biz_url("/help/center"), icon="help"),
                NavItem("Report a Bug", biz_url("/bug"), icon="bug"))

    With no extra items it's a plain link. Build ``href`` with
    :func:`~workpeg.ui.biz_url` — ``biz_url("/kanban")`` → ``/b/<id>/kanban`` —
    for the business-scoped route convention.

    Icons render at the 2px default weight (as do the built-in Search and
    Workpeg AI items); pick a different weight per item with a ``:weight``
    suffix on the icon name::

        NavItem("Kanban", biz_url("/kanban"), icon="layout-kanban:bolder")
        NavItem("Vault", biz_url("/vault"), icon="shield-lock:thin")


    On collapse the icon stays and re-centres while the label hides. See
    :class:`StaticNavItem` (never changes) and :class:`HidingNavItem` (the whole
    row hides) for the other two collapse behaviours."""

    def __init__(self, label, href, *submenu, icon="circle",
                 actions=None, on_action=None, menu=None, on_menu=None,
                 context=None):
        self.label = label
        self.href = href
        self.icon = icon
        self.submenu = submenu
        # Optional trailing actions (24px icon buttons on the row's right —
        # pin, star, history …): a list of icon names plus ONE handler that
        # receives ``(icon_name, context)`` (``context`` is this item's dict,
        # below). They reveal on row hover (:link-hover) and a tap never
        # navigates the row (the runtime swallows the link's own click after an
        # in-link tap)::
        #
        #     NavItem("Colors", biz_url("/colors"), icon="color-swatch",
        #             actions=["pin", "star"], on_action=self.nav_action,
        #             context={"label": "Colors", "id": "colors-42"})
        #
        #     def nav_action(self, name, ctx):
        #         toast(f'{name} on "{ctx["label"]}" ({ctx["id"]})')
        self.actions = actions if actions else []
        self.on_action = on_action
        # An optional overflow **menu**: a trailing ``⋯`` button opening a
        # flyout of action rows (Duplicate / Archive / Delete …) that flies out
        # to the **right** of the rail. ``menu`` is a list of item dicts —
        # ``{"name", "icon", "label"}`` plus two OPTIONAL keys, so a plain row
        # states only the exceptional: ``"tone": "danger"`` paints it
        # red/destructive, a truthy ``"disabled"`` greys it out (not-allowed
        # cursor, no fire). ``on_menu`` is ONE handler receiving
        # ``(item_name, context)``::
        #
        #     NavItem("Backlog", biz_url("/backlog"), icon="layout-kanban",
        #             menu=[{"name": "duplicate", "icon": "copy",
        #                    "label": "Duplicate", "disabled": True},
        #                   {"name": "archive", "icon": "archive",
        #                    "label": "Archive"},
        #                   {"name": "delete", "icon": "trash",
        #                    "label": "Delete", "tone": "danger"}],
        #             on_menu=self.nav_menu,
        #             context={"label": "Backlog", "id": "backlog-7"})
        self.menu = menu if menu else []
        self.on_menu = on_menu
        # A caller-supplied dict passed AS-IS to on_action / on_menu, so one
        # shared handler can tell whose row fired and act on it — put whatever
        # it needs inside (a page/board uuid, the label for a toast, a kind …).
        # The SDK never adds or reads keys. Defaults to {} so a handler can
        # subscript it safely when the caller passed nothing.
        self.context = context if context else {}

    def build(self):
        # ── flyout submenu (opens beside the rail) ──────────────────────────
        # Use len() (an empty list is truthy in JS): with no items it's a plain
        # link — no caret, no flyout — and this re-evaluates on every render, so
        # a submenu that appears/clears with state shows/hides its caret live.
        # Collapse is CSS-driven (the --pg-collapse-* vars), one rendering for
        # both states: the icon is the row's left-most child, so the item's
        # animated left padding re-centres it; the label/chevron group (Expanded,
        # so it fills the row and the chevron lands flush right) just fades while
        # the closing rail squeezes its width — it never tugs the icon.
        if len(self.submenu) > 0:
            return Menu(
                Container(
                    Expanded(Row(
                        Icon(self.icon, size=18,
                             color="var(--color-icon-primary)"),
                        # Same NavLabel hide as the plain link, wrapping the
                        # label + a flush-right chevron; both fade on collapse.
                        NavLabel(
                            _NavLabelText(self.label),
                            Spacer(),
                            Icon("chevron-right", size=14,
                                 color="var(--color-text-tertiary)"),
                        ),
                        align="center", gap=8,
                    )),
                    style={
                        "display": "flex", "alignItems": "center",
                        "height": "36px", "paddingTop": "0",
                        "paddingBottom": "0", "paddingRight": "12px",
                        "paddingLeft": "var(--pg-collapse-pl)",
                        "borderRadius": "8px", "cursor": "pointer",
                        "width": "100%", "boxSizing": "border-box",
                        "color": "var(--color-text-secondary)",
                        "transition": _TR_PAD,
                        ":hover": {"background": "var(--color-bg-active)"},
                    },
                ),
                *self.submenu, placement="right",
            )
        # ── plain link ──────────────────────────────────────────────────────
        return Link(
            Expanded(Row(
                Icon(self.icon, size=18, color="var(--color-icon-primary)"),
                # The label region uses NavLabel so it fades/squeezes on
                # collapse (the icon stays and re-centres); gap=8 sets it off
                # the icon. A Spacer right-aligns the shared hover action tray.
                NavLabel(
                    _NavLabelText(self.label),
                    Spacer(),
                    _NavActionTray(self.actions, self.on_action, self.menu,
                                   self.on_menu, self.context),
                ),
                align="center", gap=8,
            )),
            href=self.href,
            title=self.label,
            style={
                "display": "flex", "alignItems": "center",
                "width": "100%", "boxSizing": "border-box", "height": "36px",
                "paddingTop": "0", "paddingBottom": "0",
                "paddingRight": "12px",
                "paddingLeft": "var(--pg-collapse-pl)",
                "borderRadius": "8px", "color": "var(--color-text-secondary)",
                "textDecoration": "none", "transition": _TR_PAD,
                ":hover": {"background": "var(--color-bg-active)"},
                # URL-aware selected state: the router sets aria-current="page"
                # on the link whose href is the current page, so this highlight
                # persists across a refresh (unlike a hover/click-only state).
                ":current": {"background": "var(--color-bg-active)"},
            },
        )


class StaticNavItem(NavItem):
    """A nav row that does **not** change when the rail collapses — icon *and*
    label stay put (the label clips in the narrow rail). Use it for a pinned
    item you always want labelled. Build ``href`` with
    :func:`~workpeg.ui.biz_url`.

    It **subclasses** :class:`NavItem` — sharing its constructor *and* its
    hover action tray, so ``actions`` / ``on_action`` / ``menu`` / ``on_menu``
    work here identically (``StaticNavItem("Pinned", href, icon="pin",
    actions=["star"], on_action=...)``) — and overrides only ``build()`` with
    the static rendering. (Same family as :class:`NavItem`, which hides the
    label, and :class:`HidingNavItem`, which hides the whole row.)"""

    def build(self):
        return Link(
            Expanded(Row(
                Icon(self.icon, size=18, color="var(--color-icon-primary)"),
                # Plain label (no NavLabel) — it never fades; it just clips. A
                # Spacer right-aligns the shared hover action tray, so a
                # StaticNavItem carries actions/menu exactly like a NavItem.
                Container(
                    Row(_NavLabelText(self.label), Spacer(),
                        _NavActionTray(self.actions, self.on_action,
                                       self.menu, self.on_menu, self.context),
                        align="center", gap=0),
                    style={"flex": "1", "minWidth": "0", "overflow": "hidden"},
                ),
                align="center", gap=6,
            )),
            href=self.href,
            title=self.label,
            style={
                "display": "flex", "alignItems": "center",
                "width": "100%", "boxSizing": "border-box", "height": "36px",
                "paddingTop": "0", "paddingBottom": "0",
                # Fixed padding (no --pg-collapse-pl) → the icon never re-centres.
                "paddingLeft": "12px", "paddingRight": "12px",
                "borderRadius": "8px", "color": "var(--color-text-secondary)",
                "textDecoration": "none",
                ":hover": {"background": "var(--color-bg-active)"},
                ":current": {"background": "var(--color-bg-active)"},
            },
        )


class HidingNavItem(NavItem):
    """A nav row that hides **entirely** when the rail collapses — the whole row
    (icon + label) shrinks away, so it doesn't clutter the collapsed rail. Use
    it for a secondary item. Build ``href`` with :func:`~workpeg.ui.biz_url`.

    It **subclasses** :class:`NavItem` (sharing its constructor *and* its hover
    action tray — ``actions`` / ``on_action`` / ``menu`` / ``on_menu`` work
    here too) and overrides only ``build()``. (Same family as :class:`NavItem`
    and :class:`StaticNavItem`.)"""

    def build(self):
        return Link(
            Expanded(Row(
                Icon(self.icon, size=18, color="var(--color-icon-primary)"),
                # NavLabel fades the label + shared action tray on collapse; a
                # Spacer right-aligns the tray, so a HidingNavItem carries
                # actions/menu exactly like a NavItem.
                NavLabel(_NavLabelText(self.label), Spacer(),
                         _NavActionTray(self.actions, self.on_action,
                                        self.menu, self.on_menu,
                                        self.context)),
                align="center", gap=6,
            )),
            href=self.href,
            title=self.label,
            style={
                "display": "flex", "alignItems": "center",
                "width": "100%", "boxSizing": "border-box",
                "paddingTop": "0", "paddingBottom": "0",
                "paddingLeft": "var(--pg-collapse-pl)",
                "paddingRight": "12px",
                "borderRadius": "8px", "color": "var(--color-text-secondary)",
                "textDecoration": "none", "overflow": "hidden",
                # Collapse the whole row away with the rail: height → 0 + fade.
                "height": "var(--pg-collapse-item-h)",
                "opacity": "var(--pg-collapse-op)",
                "transition": _TR_HIDE,
                ":hover": {"background": "var(--color-bg-active)"},
                ":current": {"background": "var(--color-bg-active)"},
            },
        )


class NavSubItem(Component):
    """A sub-item: the indented, **icon-less** row under a group's header —
    the design's ``.pg-nav-item--sub``. Build ``href`` with
    :func:`~workpeg.ui.biz_url`::

        FoldedNavSection("Access Management",
            NavSubItem("Policies", biz_url("/access/policies")),
            NavSubItem("Users", biz_url("/access/users")),
            header=Row(Icon("shield", size=18), Text("Access Management"),
                       align="center", gap=8))

    Its own class rather than ``NavItem(icon=None)``: a :class:`NavItem` is a
    row with an icon, and every variant of it keeps that shape. A sub-item
    differs in more than the missing glyph — it is indented under its header,
    and it marks the current page with a **text-colour change only**, the
    background pill staying with the header. Both are the design's rules, not
    options on a NavItem.

    With no icon to re-centre it **hides entirely when the rail collapses**
    (like :class:`HidingNavItem`): an icon-less row in the narrow rail would
    be a 36px strip of nothing."""

    def __init__(self, label, href):
        self.label = label
        self.href = href

    def build(self):
        return Link(
            Expanded(Row(
                NavLabel(Text(self.label, style={
                    "fontSize": "14px", "fontWeight": "450",
                    "lineHeight": "16px", "whiteSpace": "nowrap",
                    "overflow": "hidden", "textOverflow": "ellipsis",
                    # Inherit, so the link's rest/hover/current colour reaches
                    # the label — the whole state of a sub-item is its colour.
                    "color": "inherit"})),
                align="center", gap=0,
            )),
            href=self.href,
            title=self.label,
            style={
                "display": "flex", "alignItems": "center",
                "width": "100%", "boxSizing": "border-box",
                "paddingTop": "0", "paddingBottom": "0",
                # Indented under the header: the rail's padding, plus the
                # width of the icon-and-gap a NavItem's label sits behind.
                "paddingLeft": "calc(var(--pg-collapse-pl) + 24px)",
                "paddingRight": "12px",
                "borderRadius": "8px", "color": "var(--color-text-secondary)",
                "textDecoration": "none", "overflow": "hidden",
                "height": "var(--pg-collapse-item-h)",
                "opacity": "var(--pg-collapse-op)",
                "transition": _TR_HIDE,
                # No background in either state — the pill is the header's.
                ":hover": {"color": "var(--color-text-primary)"},
                ":current": {"color": "var(--color-text-primary)"},
            },
        )


class NavSection(Component):
    """A titled, **collapsible** group of nav items. Click the header (title +
    chevron) to fold the items away; the chevron rotates and the content
    animates shut. Each section owns its own open state — nothing to wire.

    The header is a small caption above its items — the design's
    ``.pg-nav-sec``. To draw it as anything else, pass ``header=``: a widget
    that takes the caption's place, composed however the rail needs it::

        NavSection("Private", NavItem("Kanban", biz_url("/kanban")))
        NavSection(
            "Customer Management",
            NavItem("Clients", biz_url("/clients"), icon="users"),
            header=Row(Icon("address-book", size=18),
                       Text("Customer Management"), align="center", gap=8),
        )

    ``title`` stays the accessible name either way. Composition rather than
    an ``icon=`` argument, because an argument fixes one shape and a header
    is any shape — and because a group's look belongs to whoever draws the
    rail, not to this widget.

    Every group starts open. There is deliberately no ``open=False``: a
    constructor argument of that name is assigned by the generated
    ``_applyProps`` on EVERY render, which overwrites the State field of the
    same name — the toggle wrote ``this.state.open`` while ``build()`` read
    the clobbered ``this.open``, and the section never folded. Use
    :class:`FoldedNavSection` to start shut.
    """

    open = State(True)

    def __init__(self, title, *items, header=None):
        self.title = title
        self.items = items
        self.header = header

    def _toggle(self):
        self.open = False if self.open else True

    def _chevron(self):
        return Container(
            Icon("chevron-down", size=14,
                 color="var(--color-text-tertiary)"),
            style={
                "display": "flex", "alignItems": "center",
                "justifyContent": "center",
                "width": "16px", "height": "16px",
                "transform": ("rotate(0deg)" if self.open
                              else "rotate(-90deg)"),
                "transition": "transform 0.18s "
                              "cubic-bezier(0.4, 0, 0.2, 1)",
            },
        )

    def _items(self):
        # ── content: folds shut under the header ────────────────────────
        return Container(
            Column(*self.items, gap=2, align="stretch"),
            style={
                "overflow": "hidden",
                "maxHeight": "2000px" if self.open else "0px",
                "opacity": "1" if self.open else "0",
                "transition":
                    "max-height 0.25s cubic-bezier(0.4, 0, 0.2, 1), "
                    "opacity 0.18s cubic-bezier(0.4, 0, 0.2, 1)",
            },
        )

    def build(self):
        if self.header:
            # A composed header: whatever was passed, then the chevron. The
            # same padding, cursor and fold as the caption form — only the
            # label changes hands.
            return Column(
                GestureDetector(
                    Container(
                        Expanded(Row(
                            self.header,
                            Spacer(),
                            self._chevron(),
                            align="center", gap=4,
                        )),
                        style={
                            "display": "flex", "alignItems": "center",
                            "width": "100%", "boxSizing": "border-box",
                            "padding": "8px 8px 4px", "cursor": "pointer",
                            "userSelect": "none",
                            "transition":
                                "opacity 0.18s cubic-bezier(0.4, 0, 0.2, 1)",
                            ":rest": {"opacity": "var(--pg-collapse-op)"},
                            ":hover": {"opacity": "0.7"},
                        },
                    ),
                    on_tap=self._toggle,
                ),
                self._items(),
                gap=0,
                align="stretch",
            )
        return Column(
            # ── header: title + chevron, click to fold ──────────────────────
            GestureDetector(
                Container(
                    Expanded(Row(
                        Text(self.title, variant="caption",
                             style={
                                 # Section heading: tertiary, Label XS at
                                 # medium. When the rail closes the heading
                                 # only *fades* — it keeps its height so the
                                 # items below don't jump up.
                                 "color": "var(--color-text-tertiary)",
                                 "fontSize": "11px",
                                 # .pg-nav-sec — medium (500) in the design
                                 "fontWeight": "500", "lineHeight": "14px",
                                 "overflow": "hidden",
                                 "whiteSpace": "nowrap",
                             }),
                        Spacer(),
                        self._chevron(),
                        align="center", gap=4,
                    )),
                    style={
                        "display": "flex", "alignItems": "center",
                        "width": "100%", "boxSizing": "border-box",
                        "padding": "8px 8px 4px", "cursor": "pointer",
                        "userSelect": "none",
                        "transition":
                            "opacity 0.18s cubic-bezier(0.4, 0, 0.2, 1)",
                        # Resting opacity in the SHEET (:rest), not inline —
                        # an inline value would beat the :hover rule and the
                        # design's 0.7 hover dim would never fire.
                        ":rest": {"opacity": "var(--pg-collapse-op)"},
                        ":hover": {"opacity": "0.7"},
                    },
                ),
                on_tap=self._toggle,
            ),
            self._items(),
            gap=0,
            # stretch (not start) so a submenu item fills the row and its
            # chevron lands flush at the end, like items outside a section.
            align="stretch",
        )


class FoldedNavSection(NavSection):
    """A :class:`NavSection` that starts shut.

    A SUBCLASS rather than an argument. `open` is a State field, and any
    constructor argument of that name is assigned by the generated
    `_applyProps` on every render — which overwrites the state and leaves
    the group unable to fold at all (0.140.0 shipped exactly that). A
    subclass changes the field's DEFAULT instead, which nothing overwrites::

        FoldedNavSection("Access Management",
                         NavItem("Users", biz_url("/users")),
                         icon="shield")
    """

    open = State(False)


class NavFixed(Component):
    """The host's additions to the rail's **fixed top zone** — the rows that
    sit with the built-in Search / Workpeg AI items, above the dividing line
    and the scrollable nav, so they never scroll away. Pass it to
    :class:`Scaffold`'s ``fixed=`` slot::

        Scaffold(
            NavSection("Private", ...),        # scrolls
            fixed=NavFixed(
                NavItem("Home", biz_url("/"), icon="home"),
            ),
            main=Outlet(),
        )

    Items are ordinary ``NavItem``\\ s (actions, submenus and collapse
    behaviour all work as usual)."""

    def __init__(self, *items):
        self.items = items

    def build(self):
        return Column(*self.items, gap=2, align="stretch")


class NavHR(Component):
    """A sidebar divider — just a full-width hairline. Drop it into the nav
    (positionally, like a :class:`NavItem`) to separate groups, e.g. a primary
    item from the sections below::

        Scaffold(
            NavItem("Home", "/", icon="home"),
            NavHR(),                       # ── the line ──
            NavSection("Private", ...),
            main=Outlet(),
        )

    The Scaffold draws its own line under the fixed top zone (the static
    design's ``.pg-sidebar-mid`` border-top), so a NavHR is no longer needed
    there — use it for any *additional* divider: inside a section, between
    foot groups, wherever. Carries the same rhythm (12px above the line,
    16px below). Stays visible when the rail collapses (it has no glyph to
    re-centre)."""

    def build(self):
        return Container(style={
            "height": "1px", "flexShrink": "0",
            "background": "var(--color-border-subtle)",
            "margin": "12px 0 16px",
        })


class WorkspaceItem(Component):
    """One business row: grip · avatar(initial) · name/plan · checkmark.
    All locals live in __init__ so build() is a single return."""

    def __init__(self, business, current_id):
        self.name = business["name"]
        self.uuid = business["uuid"]
        self.plan = "Free Plan"
        self.initial = business["name"][0] if business["name"] else "?"
        self.is_active = business["uuid"] == current_id
        # Resolve the active-vs-default styling here so build() is a single
        # return.
        # None (not "transparent") when inactive: applyStyle skips null, so the
        # inline background doesn't exist and the :hover rule below can win
        # (an inline `transparent` would out-specify the hover class).
        self.row_bg = ("var(--color-surface-sunken2)" if self.is_active
                       else None)
        self.name_color = ("var(--color-text-primary)" if self.is_active
                           else "var(--color-text-secondary)")
        # .pg-ws-name.is-active — medium (500); inactive stays normal (400)
        self.name_weight = "500" if self.is_active else "400"
        self.check_display = "flex" if self.is_active else "none"

    def go(self):
        # Switch business with an SPA navigation (no full-page reload, so no
        # asset-redownload pause after the click). The runtime remounts the
        # shell on the changed [business_id] — on_mount re-runs and re-fetches,
        # so the sidebar/navItems, data and state are all rebuilt fresh — and the
        # AppShell shows its loader instantly while the new data loads.
        navigate(f"/b/{self.uuid}")

    def build(self):
        return GestureDetector(
            Container(
                SizedBox(
                    Row(
                        # grip (14px, pulled toward the avatar by -4px)
                        Container(
                            Icon("grip-vertical", size=14, weight="thin"),
                            style={
                                "display": "flex", "alignItems": "center",
                                "justifyContent": "center",
                                "width": "14px", "height": "14px",
                                "color": "var(--color-icon-primary)",
                                "flexShrink": "0", "marginRight": "-4px",
                            },
                        ),
                        # avatar (xs, 20px — sunken2 fill + subtle ring)
                        Container(
                            Text(self.initial, style={
                                # .pg-avatar — medium (500)
                                "fontSize": "10px", "fontWeight": "500",
                                "color": "var(--color-text-placeholder)",
                                "lineHeight": "1",
                            }),
                            style={
                                "width": "20px", "height": "20px",
                                "borderRadius": "9999px",
                                "background": "var(--color-surface-sunken2)",
                                "border":
                                    "0.83px solid var(--color-border-subtle)",
                                "display": "flex", "alignItems": "center",
                                "justifyContent": "center", "flexShrink": "0",
                            },
                        ),
                        # name + plan
                        Container(
                            Column(
                                Text(self.name, style={
                                    "fontSize": "12px",
                                    "fontWeight": self.name_weight,
                                    "color": self.name_color,
                                    "whiteSpace": "nowrap", "overflow": "hidden",
                                    "textOverflow": "ellipsis",
                                    "lineHeight": "14px",
                                }),
                                Text(self.plan, style={
                                    "fontSize": "11px",
                                    "color": "var(--color-text-tertiary)",
                                    "lineHeight": "14px",
                                    "whiteSpace": "nowrap",
                                }),
                                gap=0, align="start",
                            ),
                            style={"flex": "1", "overflow": "hidden",
                                   "minWidth": "0"},
                        ),
                        # checkmark — present always, toggled via display
                        Container(
                            Icon("check", size=14, weight="thin"),
                            style={
                                "display": self.check_display,
                                "alignItems": "center",
                                "justifyContent": "center",
                                "color": "var(--color-icon-primary)",
                                "flexShrink": "0",
                            },
                        ),
                        align="center", gap=8, justify="space_between"
                    ),
                    width=infinity,
                ),
                style={
                    "display": "flex", "alignItems": "center", "gap": "8px",
                    "padding": "6px", "borderRadius": "8px",
                    "cursor": "pointer",
                    "transition":
                        "background 0.18s cubic-bezier(0.4, 0, 0.2, 1)",
                    "background": self.row_bg,
                    "width": "100%", "boxSizing": "border-box",
                    # Hover — surface-sunken2 (skipped for the active row,
                    # which already shows it inline).
                    ":hover": {"background": "var(--color-surface-sunken2)"},
                },
            ),
            on_tap=self.go,
        )


class DropdownAction(Component):
    """One row in the user dropdown — leading icon + label, optionally a
    trailing chevron (a submenu affordance) — rendered as a business-scoped
    :class:`Link`. Mirrors the rework's ``.pg-dropdown-action``."""

    def __init__(self, label, icon, to, chevron=False):
        self.label = label
        self.icon = icon
        self.to = to
        self.chevron = chevron

    def build(self):
        if self.chevron:
            return Link(
                Row(
                    Icon(self.icon, size=18, weight="thin",
                         color="var(--color-icon-primary)"),
                    Text(self.label, style={
                        "fontSize": "14px",
                        "lineHeight": "normal",
                        "whiteSpace": "nowrap", "overflow": "hidden",
                        "textOverflow": "ellipsis",
                        "color": "var(--color-text-primary)"}),
                    Spacer(),
                    Icon("chevron-right", size=14, weight="thin",
                         color="var(--color-text-tertiary)"),
                    align="center", gap=10,
                ),
                href=self.to,
                style={
                    "display": "flex", "alignItems": "center", "gap": "10px",
                    "height": "36px", "padding": "0 9px",
                    "borderRadius": "var(--radius)",
                    "cursor": "pointer", "width": "100%",
                    "boxSizing": "border-box",
                    "color": "var(--color-text-primary)",
                    "textDecoration": "none",
                    # .pg-dropdown-action:hover
                    ":hover": {"background": "var(--color-surface-sunken2)"},
                },
            )
        return Link(
            Row(
                Icon(self.icon, size=18, weight="thin",
                     color="var(--color-icon-primary)"),
                Text(self.label, style={
                    "fontSize": "14px",
                    "lineHeight": "normal",
                    "color": "var(--color-text-primary)"}),
                align="center", gap=10,
            ),
            href=self.to,
            style={
                "display": "flex", "alignItems": "center", "gap": "10px",
                "height": "36px", "padding": "0 9px",
                "borderRadius": "var(--radius)",
                "cursor": "pointer", "width": "100%",
                "boxSizing": "border-box",
                "color": "var(--color-text-primary)",
                "textDecoration": "none",
                # .pg-dropdown-action:hover
                ":hover": {"background": "var(--color-surface-sunken2)"},
            },
        )


class DropdownSubmenu(Component):
    """A dropdown row that opens a flyout submenu to its right (a nested
    :class:`Menu`) — the rework's ``.pg-dropdown-action.has-submenu`` +
    ``#pgHelpDropdown``. The trigger is a non-link row with a chevron; the
    ``*items`` float in their own panel and the parent dropdown stays open."""

    def __init__(self, label, icon, *items):
        self.label = label
        self.icon = icon
        self.items = items

    def build(self):
        # Returned directly (no SizedBox): as a flex child of the dropdown's
        # stretch column the menu fills the row width, so the trigger's chevron
        # lands flush at the end. The flyout items sit in one gap-1 column at the
        # same width as the parent panel so they're spaced alike.
        return Menu(
            Container(
                # SizedBox(width=infinity) forces the row to the full panel
                # width (like WorkspaceItem), so the Spacer drives the chevron
                # flush to the end — level with the workspace check above.
                SizedBox(
                    Row(
                        Icon(self.icon, size=18, weight="thin",
                             color="var(--color-icon-primary)"),
                        Text(self.label, style={
                            "fontSize": "14px",
                            "lineHeight": "normal",
                            "whiteSpace": "nowrap", "overflow": "hidden",
                            "textOverflow": "ellipsis",
                            "color": "var(--color-text-primary)"}),
                        Spacer(),
                        Icon("chevron-right", size=14, weight="thin",
                             color="var(--color-text-tertiary)"),
                        align="center", gap=10,
                    ),
                    width=infinity,
                ),
                style={
                    "display": "flex", "alignItems": "center",
                    "height": "36px", "padding": "0 9px",
                    "borderRadius": "var(--radius)", "cursor": "pointer",
                    "width": "100%", "boxSizing": "border-box",
                    "color": "var(--color-text-primary)",
                    # .pg-dropdown-action.has-submenu:hover
                    ":hover": {"background": "var(--color-surface-sunken2)"},
                },
            ),
            Container(
                Column(*self.items, gap=1, align="stretch"),
                style={"width": "202px", "boxSizing": "border-box"},
            ),
            placement="right",
        )


class WorkspacePopup(Component):
    """The user dropdown panel: a scrollable list of :class:`WorkspaceItem`
    rows, then the standard actions — Add new business, Profile, Settings, and
    (with a submenu chevron) Help and Support / Log out — split by dividers.
    Shared by both :class:`UserSwitcher` triggers (the collapsed avatar and the
    expanded profile row), so the panel lives in one place. Mirrors the rework's
    ``#pgMainDropdown``."""

    def __init__(self, businesses, current_id):
        self.businesses = businesses
        self.current_id = current_id

    def build(self):
        return Container(
            Column(
                # the workspace list scrolls; the actions below stay put. Cap it
                # at 3.5 rows so a 4th business peeks in — a natural "there's more,
                # scroll" cue. A row is 40px (28px content + 6px×2 padding) with an
                # 8px gap between rows: 3 full rows + 3 gaps + half a row.
                Container(
                    Column(
                        *[WorkspaceItem(b, self.current_id, key=b["uuid"])
                          for b in self.businesses],
                        gap=8, align="stretch",
                    ),
                    style={"maxHeight": "calc(3.5 * 40px + 3 * 8px)",
                           "overflowY": "auto",
                           # the design's .pg-ws-list thin scrollbar
                           "scrollbarWidth": "thin",
                           "scrollbarColor":
                               "rgba(128, 128, 128, 0.15) transparent"},
                ),
                DropdownAction("Add new business", "plus",
                               to=f"/b/{self.current_id}/new"),
                Container(style={
                    "height": "1px",
                    "background": "var(--color-border-subtle)",
                    "margin": "6px 0",
                }),
                DropdownAction("Profile", "user",
                               to=f"/b/{self.current_id}/profile"),
                DropdownAction("Settings", "settings",
                               to=f"/b/{self.current_id}/settings"),
                Container(style={
                    "height": "1px",
                    "background": "var(--color-border-subtle)",
                    "margin": "6px 0",
                }),
                DropdownSubmenu(
                    "Help and Support", "help",
                    DropdownAction("Help Center", "help",
                                   to=f"/b/{self.current_id}/help"),
                    DropdownAction("Report a Bug", "bug",
                                   to=f"/b/{self.current_id}/bug"),
                ),
                DropdownAction("Log out", "logout", to="/login"),
                gap=1, align="stretch",
            ),
            # No own background: it fills the menu panel, so the dropdown is one
            # uniform surface with a single border outline (no inner two-tone).
            # 232px inside the menu panel's 8px padding + 1px border = the
            # design's 250px dropdown width.
            style={"width": "232px", "boxSizing": "border-box"},
        )


class UserSwitcher(Component):
    """Bottom profile row + workspace popup. The trigger differs by `collapsed`
    (avatar only vs the full name/plan row); both open the same
    :class:`WorkspacePopup`. All build-time values resolved in __init__."""

    def __init__(self, businesses, current_id):
        self.businesses = businesses or []
        self.current_id = current_id
        self.current_name = next(
            (b["name"] for b in self.businesses if b["uuid"] == current_id), ""
        )

    def build(self):
        # One rendering for both states: the gravatar is the row's left-most
        # child, so the trigger's animated left padding re-centres it; the
        # name/plan + selector (Expanded so the selector is flush right) just
        # fade while the closing rail squeezes their width.
        return SizedBox(
            Menu(
                Container(
                    Expanded(Row(
                        GravatarImage(user.email, initials=user.initials,
                                      width=32),
                        Container(
                            Row(
                                Column(
                                    Text(
                                        f"{user.first_name} "
                                        f"{user.last_name}",
                                        style={
                                            # .pg-user-name — label-lg (14),
                                            # medium (500), primary, lh 16.
                                            "fontSize": "14px",
                                            "fontWeight": "500",
                                            "lineHeight": "16px",
                                            "color":
                                                "var(--color-text-primary)",
                                            # nowrap so the name keeps to one
                                            # line as the rail squeezes its width
                                            # — otherwise it wraps and the row
                                            # (and switcher) grows taller.
                                            "whiteSpace": "nowrap",
                                            "overflow": "hidden",
                                            "textOverflow": "ellipsis",
                                        },
                                    ),
                                    Text(self.current_name, style={
                                        # Business name — label-md (12),
                                        # secondary, lh 14.
                                        "fontSize": "12px",
                                        "lineHeight": "14px",
                                        "color": "var(--color-text-secondary)",
                                        "whiteSpace": "nowrap",
                                        "overflow": "hidden",
                                        "textOverflow": "ellipsis",
                                    }),
                                    gap=0, align="start",
                                ),
                                Spacer(),
                                # 16px — the design's .pg-user-expand .ti uses
                                # the default --icon-size (16px), not the 20px
                                # the collapse toggle uses.
                                Icon("selector", size=16,
                                     color="var(--color-text-tertiary)"),
                                align="center", gap=8,
                            ),
                            style={
                                "flex": "1", "minWidth": "0",
                                "overflow": "hidden", "marginLeft": "8px",
                                "opacity": "var(--pg-collapse-op)",
                                "transition": _TR_OP,
                            },
                        ),
                        align="center", gap=0,
                    )),
                    style={
                        # Switcher row — padding 6px 8px, radius 8, hover
                        # sunken.
                        "display": "flex", "alignItems": "center",
                        "paddingTop": "6px", "paddingBottom": "6px",
                        "paddingRight": "8px",
                        "paddingLeft": "var(--pg-collapse-pl-sw)",
                        "borderRadius": "8px", "width": "100%",
                        "boxSizing": "border-box", "transition": _TR_PAD,
                        ":hover": {"background": "var(--color-surface-sunken)"},
                    },
                ),
                WorkspacePopup(self.businesses, self.current_id),
                placement="top",
            ),
            width=infinity,
        )


class Scaffold(Component):
    """The Workpeg app shell: sidebar · ``main`` · optional ``attached`` panel.

    Self-contained: it gates on the signed-in session; the chrome loads the
    user's businesses itself, renders the switcher, and caches the active
    business (the ``cachedBusiness`` cookie) so a returning user lands straight
    back in it — a host never threads auth, a business list or that
    bookkeeping in. It reads the active business from the URL, so it only
    works mounted under a ``/b/<business_uuid>`` route and every link it
    builds is ``/b/<business_uuid>/…``.

    **Bundle-drawn chrome.** Only the slots below compile into the app; the
    shell around them — the rail's header (logo + collapse toggle), the
    built-in Search / Workpeg AI rows, the business switcher, the top bar's
    SDK actions (History / Incognito / Apps / AI) — is drawn at runtime by the
    standalone ``scaffold.js`` (bundled next to the app and published to the
    CDN, like the ``ai.js`` chat surface). The Workpeg team updates the
    shell's design out of band; apps pick it up without a rebuild. The
    compiled slot content renders into stable slot roots the chrome adopts —
    the ``build()`` below emits exactly that handoff.

    It publishes the active business *name* to ``store.business`` once loaded,
    so a page can read it (e.g. for a headline) without fetching the list a
    second time — declare ``store = Store(business="")`` on your Router.

    Slots (children):
      * ``*sidebar`` — the nav widgets (positional), the **scrollable** list
        under the dividing line (e.g. ``NavItem`` / ``NavSection``). A
        trailing ``Spacer()`` pushes the widgets after it to the foot.
      * ``fixed`` — a :class:`NavFixed` of rows that join the built-in
        Search / Workpeg AI in the fixed top zone, above the line — they
        never scroll away (Home, typically).
      * ``top_nav`` — **your** content for the left of the top bar: any widget
        (a page title ``Text``, a share ``Button``, a breadcrumb ``Row`` —
        anything, or nothing). The top bar always renders because its RIGHT
        holds SDK-owned chrome actions (Apps, AI) you can't change. It sits
        above ``main`` and updates live from reactive state — set
        ``top_nav=Text(store.page_title)`` and have each page write
        ``store.page_title`` for a per-page title.
      * ``main`` — the page body. In a routed app this is an ``Outlet()``.
      * ``attached`` — an optional panel rendered to the right of ``main``
        (an inspector, a canvas, a chat). Hidden when omitted.

    Sidebar collapse is **owned by the chrome** — its own toggle button (a
    window-control, not a host knob). It's purely visual: the toggle flips the
    ``.pg-collapsed`` class on ``<html>`` (no re-render), and the rail, its
    labels and the switcher animate between widths off Pegment's
    ``--pg-collapse-*`` custom properties. ``NavItem``/``NavSection`` carry no
    collapse flag — they respond to that class automatically — so a host just
    lists its nav and never threads collapse state through.
    """

    def __init__(self, *sidebar, main, attached=None, fixed=None,
                 top_nav=None):
        self.sidebar = sidebar
        self.main = main
        self.attached = attached
        self.fixed = fixed
        self.top_nav = top_nav

    def build(self):
        # Auth-gated, then pure handoff: the five slot roots (nav, fixed,
        # top_nav, main, attached — `main` holds the Outlet, which must exist
        # synchronously for the router to wire the routed child into it). The
        # runtime renders these and hands the host element to scaffold.js,
        # which draws the chrome around them (see Workpeg._scaffoldMount).
        # gap=8 between the host's nav entries — the design's .pg-nav-sections
        # rhythm; scroll="visible" keeps the column full-height so a trailing
        # host Spacer() can push items to the rail's foot.
        return Authenticated(ScaffoldSlots(
            Column(*self.sidebar, gap=8, align="stretch", scroll="visible"),
            self.fixed,
            self.top_nav,
            self.main,
            self.attached,
        ))
